export interface SagaTreeFaceAnchorBarycentric {
  readonly u: number;
  readonly v: number;
  readonly w: number;
}

export interface SagaTreeFaceAnchorTriangleBinding {
  readonly nodeIdentity: string;
  readonly primitiveIndex: number;
  readonly triangleIndex: number;
  readonly barycentric: SagaTreeFaceAnchorBarycentric;
}

export interface SagaTreeFaceAnchorsManifestV1 {
  readonly contractVersion: typeof FACE_ANCHORS_CONTRACT_VERSION;
  readonly anchors: Readonly<Partial<Record<SagaTreeFaceAnchorId, SagaTreeFaceAnchorTriangleBinding>>>;
}

export interface SagaTreeFaceAnchorBindingValidationIssue {
  readonly code:
    | 'invalid_anchor_id'
    | 'invalid_node_identity'
    | 'invalid_primitive_index'
    | 'invalid_triangle_index'
    | 'invalid_barycentric'
    | 'contract_version_mismatch';
  readonly anchorId?: SagaTreeFaceAnchorId;
  readonly detail: string;
}

export interface SagaTreeFaceAnchorBindingValidationResult {
  readonly ok: boolean;
  readonly issues: readonly SagaTreeFaceAnchorBindingValidationIssue[];
}

export interface AvatarMorphParamMeta {
  key: AvatarMorphParamKey;
  group: AvatarMorphParamGroup;
  labelDe: string;
  min: -1;
  max: 1;
  default: 0;
  step: number;
}

export interface AvatarMorphColorsV1 {
  skin: string;
  eyes: string;
  hair: string;
}

export interface AvatarMorphTraitSlotsV1 {
  markings: readonly string[];
  scars: readonly string[];
  cybernetics: readonly string[];
}

export interface SagaTreeAvatarMorphStateV1 {
  contractVersion: typeof MORPH_CONTRACT_VERSION;
  body: AvatarMorphBodyValues;
  face: AvatarMorphFaceValues;
  colors: AvatarMorphColorsV1;
  traits: AvatarMorphTraitSlotsV1;
}

export interface AvatarMorphCapabilities {
