}

export interface AvatarMorphValidationResult {
  ok: boolean;
  state: SagaTreeAvatarMorphStateV1;
  /** Unknown keys that were ignored (fail-safe). */
  ignoredKeys: readonly string[];
  /** Human-readable DE reasons when values were clamped/rejected. */
  warnings: readonly string[];
}

export interface CharacterAttributesDto {
  strength: number;
  dexterity: number;
  endurance: number;
  mind: number;
  perception: number;
  charisma: number;
}

export interface CharacterAttributeStorageDto extends Partial<CharacterAttributesDto> {
  constitution?: number;
  intelligence?: number;
  wisdom?: number;
}

export interface CharacterAvatarDto {
  schema_version: 1;
  /** @deprecated Prefer `source`. Kept for legacy readers; always `m3-character-studio`. */
  provider: 'm3-character-studio';
  /**
   * Avatar origin — never a capability proof (#6 owns capabilities).
   * Missing → resolve via resolveAvatarSource (legacy provider → sagatree).
   */
  source?: 'sagatree' | 'import' | 'meshy';
  preset: string;
  model_format: CharacterAvatarFormat;
  model_url?: string;
  traits: { head?: string; ears?: string; hair?: string; clothing?: string; accessory?: string };
  /** hair/skin required for legacy; eyes optional until morph migration. */
  colors: { hair: string; skin: string; eyes?: string };
  body: { height: number; size: number };
  morph_contract_version?: 'SagaTreeAvatarMorphV1';
  /** Validated morph state — prefer morph-contract helpers over raw writes. */
  morph?: SagaTreeAvatarMorphStateV1;
  /**
   * Avatar V2 template ingress (#260) — optional; ignored by legacy readers.
   * `template_id` e.g. `species-template:dwarf`; `body_family` from template pack.
   */
  template_id?: string;
  body_family?: 'standard' | 'compact' | 'heavy' | 'custom';
  /** V2 anatomy; legacy `non-humanoid` still readable via composition mapper. */
  anatomy?: 'humanoid' | 'custom-creature' | 'non-humanoid' | 'unknown';
  body_compatibility?: 'standard' | 'compact' | 'heavy' | 'custom' | 'unknown';
  /** V2 modularity; legacy `none` maps to monolithic. */
  modularity?: 'modular-parts' | 'limited' | 'monolithic' | 'none';
  /** Logical starter wardrobe ids applied as basic outfit (not inventory). */
  starter_wardrobe?: readonly string[];
  /**
   * Manual Face Mapping bindings for this character (#persist).
   * SagaTreeFaceAnchorsV1 — mesh triangle anchors only; never webcam landmarks.
   * Optional; ignored by legacy readers. Wins over sibling face-anchors.json sidecar.
   */
  face_anchors?: SagaTreeFaceAnchorsManifestV1;
}

export interface CharacterAppearanceDto {
  body_size: number;
  height: number;
  face_features: string;
  hair_style: string;
  hair_color: string;
  skin_tone: string;
  clothing: string;
  gender_reading?: CharacterGenderReading;
  avatar?: CharacterAvatarDto;
  /**
   * Optional personal LookProfile override for player-character resolution (#347).
   * Null/omitted → inherit saga/session/system. Must be active + owned when set.
   */
  personal_look_profile_id?: string | null;
}

export interface AbilityDto {
  id: string;
  name: string;
  description: string;
  type: 'combat' | 'magic' | 'skill';
  cost: number;
  effect: string;
  source?: string;
  rank?: 'I' | 'II' | 'III' | 'IV' | 'V';
  action_type?: 'Passiv' | 'Hauptaktion' | 'Bewegung' | 'Reaktion';
  tags?: string[];
  usage_limit?: string;
}

export interface ItemDto {
  id: string;
  name: string;
  description: string;
  type: ItemType;
  quantity: number;
  load?: 0 | 1 | 2 | 3;
  cost?: 0 | 1 | 2 | 3 | 4 | 5;
